   199		}
   200	
   201		if existing != nil && force {
   202			if pruneErr := pruneV2CheckpointForForce(ctx, repo, v2Store, info.CheckpointID); pruneErr != nil {
   203				return fmt.Errorf("failed to reset existing v2 checkpoint %s before force migration: %w", info.CheckpointID, pruneErr)
   204			}
   205		}
   206	
   207		summary, err := v1Store.ReadCommitted(ctx, info.CheckpointID)
   208		if err != nil {
   209			return fmt.Errorf("failed to read v1 summary: %w", err)
   210		}
   211		if summary == nil {
   212			return fmt.Errorf("v1 checkpoint %s has no summary", info.CheckpointID)
   213		}
   214	
   215		compactFailed := false
   216		shouldCopyTaskMetadata := false
   217		skippedMissingSessions := 0
   218		migratedSessions := 0
   219		v1ToV2SessionIdx := make(map[int]int, len(summary.Sessions))
   220	
   221		for sessionIdx := range len(summary.Sessions) {
   222			content, skipped, readErr := readV1SessionForMigration(ctx, out, prefix, v1Store, info.CheckpointID, sessionIdx)
   223			if skipped {
   224				skippedMissingSessions++
   225				continue
   226			}
   227			if readErr != nil {
   228				return fmt.Errorf("failed to read v1 session %d: %w", sessionIdx, readErr)
   229			}
   230			if content.Metadata.IsTask {
   231				shouldCopyTaskMetadata = true
   232			}
   233	
   234			opts := buildMigrateWriteOpts(content, info, summary.CombinedAttribution)
   235	
   236			compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata)
   237			if compacted != nil {
   238				opts.CompactTranscript = compacted
   239				opts.CompactTranscriptStart = computeCompactOffset(ctx, content.Transcript, compacted, content.Metadata)
   240			} else if len(content.Transcript) > 0 {
   241				compactFailed = true
   242			}
   243	
   244			if writeErr := v2Store.WriteCommitted(ctx, opts); writeErr != nil {
   245				return fmt.Errorf("failed to write v2 session %d: %w", sessionIdx, writeErr)
   246			}
   247			v1ToV2SessionIdx[sessionIdx] = migratedSessions
   248			migratedSessions++
   249		}
   250	
   251		if migratedSessions == 0 {
   252			return fmt.Errorf("%w: v1 metadata lists %d session(s), but no transcript/session content exists for any of them", errNoMigratableSessions, len(summary.Sessions))
   253		}
   254	
   255		// Copy task metadata trees from v1 to v2 /full/current
   256		if shouldCopyTaskMetadata {
   257			if taskErr := copyTaskMetadataToV2(ctx, repo, v1Store, v2Store, info.CheckpointID, summary, v1ToV2SessionIdx); taskErr != nil {
   258				logging.Warn(ctx, "failed to copy task metadata to v2",
   259					slog.String("checkpoint_id", string(info.CheckpointID)),
   260					slog.String("error", taskErr.Error()),
   261				)
   262			}
   263		}
   264	
   265		switch {
   266		case compactFailed && skippedMissingSessions > 0:
   267			fmt.Fprintf(out, "%s done (compact transcript not generated; skipped %d session(s) with missing transcript/session content)\n", prefix, skippedMissingSessions)
   268		case compactFailed:
   269			fmt.Fprintf(out, "%s done (compact transcript not generated)\n", prefix)
   270		case skippedMissingSessions > 0:
   271			fmt.Fprintf(out, "%s done (skipped %d session(s) with missing transcript/session content)\n", prefix, skippedMissingSessions)
   272		default:
   273			fmt.Fprintf(out, "%s done\n", prefix)
   274		}
   275	
   276		return nil
   277	}
   278	
   279	func readV1SessionForMigration(ctx context.Context, out io.Writer, prefix string, v1Store *checkpoint.GitStore, checkpointID id.CheckpointID, sessionIdx int) (*checkpoint.SessionContent, bool, error) {
   280		content, readErr := v1Store.ReadSessionContent(ctx, checkpointID, sessionIdx)
   281		if readErr != nil {
   282			if errors.Is(readErr, checkpoint.ErrNoTranscript) {
   283				warnMissingV1Session(ctx, out, prefix, checkpointID, sessionIdx, readErr)
   284				return nil, true, nil
   285			}
   286			return nil, false, fmt.Errorf("read v1 session content: %w", readErr)
   287		}
   288		return content, false, nil
   289	}
   290	
   291	func warnMissingV1Session(ctx context.Context, out io.Writer, prefix string, checkpointID id.CheckpointID, sessionIdx int, err error) {
   292		fmt.Fprintf(out, "%s warning: skipping v1 session %d because checkpoint metadata lists it, but no transcript/session content exists for that session\n", prefix, sessionIdx)
   293		logging.Warn(ctx, "skipping v1 session with missing transcript during checkpoint migration",
   294			slog.String("checkpoint_id", checkpointID.String()),
   295			slog.Int("session_index", sessionIdx),
   296			slog.String("error", err.Error()),
   297		)
   298	}
