   300	func pruneV2CheckpointForForce(ctx context.Context, repo *git.Repository, v2Store *checkpoint.V2GitStore, cpID id.CheckpointID) error {
   301		for _, refName := range []plumbing.ReferenceName{
   302			plumbing.ReferenceName(paths.V2MainRefName),
   303			plumbing.ReferenceName(paths.V2FullCurrentRefName),
   304		} {
   305			if err := pruneV2CheckpointRef(ctx, repo, v2Store, refName, cpID); err != nil {
   306				return err
   307			}
   308		}
   309		return nil
   310	}
