   312	func pruneV2CheckpointRef(ctx context.Context, repo *git.Repository, v2Store *checkpoint.V2GitStore, refName plumbing.ReferenceName, cpID id.CheckpointID) error {
   313		parentHash, rootTreeHash, err := v2Store.GetRefState(refName)
   314		if err != nil {
   315			if errors.Is(err, plumbing.ErrReferenceNotFound) {
   316				return nil
   317			}
   318			return fmt.Errorf("failed to get v2 ref state for %s: %w", refName, err)
   319		}
   320	
   321		rootTree, err := repo.TreeObject(rootTreeHash)
   322		if err != nil {
   323			return fmt.Errorf("failed to read v2 tree for %s: %w", refName, err)
   324		}
   325		if _, err := rootTree.Tree(cpID.Path()); err != nil {
   326			return nil //nolint:nilerr // Checkpoint is absent from this ref, so there is nothing to prune.
   327		}
   328	
   329		shardPrefix := string(cpID[:2])
   330		shardSuffix := string(cpID[2:])
   331		newRoot, err := checkpoint.UpdateSubtree(repo, rootTreeHash,
   332			[]string{shardPrefix},
   333			nil,
   334			checkpoint.UpdateSubtreeOptions{
   335				MergeMode:   checkpoint.MergeKeepExisting,

