   627	// copyTaskMetadataToV2 copies task metadata files (subagent transcripts, checkpoint JSONs)
   628	// from the v1 branch to the v2 /full/current ref via tree surgery.
   629	func copyTaskMetadataToV2(ctx context.Context, repo *git.Repository, _ *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, cpID id.CheckpointID, summary *checkpoint.CheckpointSummary, v1ToV2SessionIdx map[int]int) error {
   630		// Resolve the v1 branch tree
   631		v1Tree, err := resolveV1CheckpointTree(repo, cpID)
   632		if err != nil {
   633			return err
   634		}
   635	
   636		// Legacy v1 layout stores task metadata at checkpoint root: <cp>/tasks/<tool-use-id>/...
   637		// Prefer attaching this tree to the latest session in v2.
   638		if rootTasksTree, rootTasksErr := v1Tree.Tree("tasks"); rootTasksErr == nil {
   639			if latestSessionIdx, ok := latestMigratedV2SessionIndex(v1ToV2SessionIdx); ok {
   640				if spliceErr := spliceTasksTreeToV2(ctx, repo, v2Store, cpID, latestSessionIdx, rootTasksTree.Hash); spliceErr != nil {
   641					return fmt.Errorf("latest session task tree splice failed: %w", spliceErr)
   642				}
   643			}
   644		}
   645	
   646		for sessionIdx := range len(summary.Sessions) {
   647			sessionDir := strconv.Itoa(sessionIdx)
   648			sessionTree, sessionErr := v1Tree.Tree(sessionDir)
   649			if sessionErr != nil {
   650				continue
   651			}
   652	
   653			tasksTree, tasksErr := sessionTree.Tree("tasks")
   654			if tasksErr != nil {
   655				continue // No tasks directory in this session
   656			}
   657	
   658			v2SessionIdx, ok := v1ToV2SessionIdx[sessionIdx]
   659			if !ok {
   660				continue
   661			}
   662	
   663			if spliceErr := spliceTasksTreeToV2(ctx, repo, v2Store, cpID, v2SessionIdx, tasksTree.Hash); spliceErr != nil {
   664				return fmt.Errorf("session %d task tree splice failed: %w", sessionIdx, spliceErr)
   665			}
   666		}
   667	
   668		return nil
   669	}
   670	
   671	func latestMigratedV2SessionIndex(v1ToV2SessionIdx map[int]int) (int, bool) {
   672		latest := -1
   673		for _, v2SessionIdx := range v1ToV2SessionIdx {
   674			if v2SessionIdx > latest {
   675				latest = v2SessionIdx
   676			}
   677		}
   678		if latest < 0 {
   679			return 0, false
   680		}
   681		return latest, true
   682	}
